      for (const x of [-0.85, -0.3, 0.3, 0.85]) box([x, 0.45, -0.7], [0.04, 0.9, 0.62], C.white);
      p("cylinder", [0, 0.9, -0.7], [0.7, 1.9, 0.7], C.white, [0, 0, Math.PI / 2]); // 拱頂
      for (const [x, z] of [[-0.8, -0.38], [0.8, -0.38], [-0.8, 0.38], [0.8, 0.38]]) post(x, z, 0.75, C.ink, 0.03);
